// design.sv - generated by scripts/build_eda_playground.sh. Do not edit; edit rtl/ instead.
`timescale 1ns/1ps

// ==== rtl/pe.sv ====
// ---------------------------------------------------------------------------
// pe.sv - Processing element for an output-stationary systolic array.
// Multiplies signed INT8 operands, accumulates into a signed 32-bit register,
// and forwards A to the right and B downward one cycle later.
// ---------------------------------------------------------------------------
module pe #(
  parameter int DW = 8,   // operand width
  parameter int AW = 32   // accumulator width
) (
  input  logic                 clk,
  input  logic                 rst_n,
  input  logic                 clr,     // synchronous clear of acc and pipeline regs
  input  logic                 en,      // compute enable
  input  logic signed [DW-1:0] a_in,
  input  logic signed [DW-1:0] b_in,
  output logic signed [DW-1:0] a_out,
  output logic signed [DW-1:0] b_out,
  output logic signed [AW-1:0] acc
);
  logic signed [2*DW-1:0] prod;
  assign prod = a_in * b_in;   // both operands signed -> signed product

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      a_out <= '0;
      b_out <= '0;
      acc   <= '0;
    end else if (clr) begin
      a_out <= '0;
      b_out <= '0;
      acc   <= '0;
    end else if (en) begin
      a_out <= a_in;
      b_out <= b_in;
      acc   <= acc + {{(AW-2*DW){prod[2*DW-1]}}, prod};  // sign-extend to AW bits
    end
  end
endmodule

// ==== rtl/systolic_array.sv ====
// ---------------------------------------------------------------------------
// systolic_array.sv - N x N grid of PEs.
// a_left[i] enters row i from the left, b_top[j] enters column j from the top.
// PE(i,j) accumulates C[i][j]. Results are exposed as a flat bus:
//   acc_flat[(i*N+j)*AW +: AW] = C[i][j]
// ---------------------------------------------------------------------------
module systolic_array #(
  parameter int N  = 4,
  parameter int DW = 8,
  parameter int AW = 32
) (
  input  logic              clk,
  input  logic              rst_n,
  input  logic              clr,
  input  logic              en,
  input  logic [N*DW-1:0]   a_left,     // row i at [i*DW +: DW]
  input  logic [N*DW-1:0]   b_top,      // col j at [j*DW +: DW]
  output logic [N*N*AW-1:0] acc_flat
);
  // Horizontal A wires: a_h[i][j] is the input to PE(i,j); a_h[i][N] is unused.
  // Vertical B wires:   b_v[i][j] is the input to PE(i,j); b_v[N][j] is unused.
  logic [DW-1:0] a_h [N][N+1];
  logic [DW-1:0] b_v [N+1][N];

  genvar i, j;
  generate
    for (i = 0; i < N; i++) begin : g_edge_a
      assign a_h[i][0] = a_left[i*DW +: DW];
    end
    for (j = 0; j < N; j++) begin : g_edge_b
      assign b_v[0][j] = b_top[j*DW +: DW];
    end

    for (i = 0; i < N; i++) begin : g_row
      for (j = 0; j < N; j++) begin : g_col
        logic signed [AW-1:0] acc_ij;
        pe #(.DW(DW), .AW(AW)) u_pe (
          .clk   (clk),
          .rst_n (rst_n),
          .clr   (clr),
          .en    (en),
          .a_in  (a_h[i][j]),
          .b_in  (b_v[i][j]),
          .a_out (a_h[i][j+1]),
          .b_out (b_v[i+1][j]),
          .acc   (acc_ij)
        );
        assign acc_flat[(i*N+j)*AW +: AW] = acc_ij;
      end
    end
  endgenerate
endmodule

// ==== rtl/accel_core.sv ====
// ---------------------------------------------------------------------------
// accel_core.sv - Control FSM + input skewing + systolic array + result buffer.
//
// Computes C = A x B for N x N signed INT8 matrices.
//   a_mat[(i*N+k)*8 +: 8] = A[i][k]
//   b_mat[(k*N+j)*8 +: 8] = B[k][j]
//   c_mat[(i*N+j)*32 +: 32] = C[i][j]
//
// Skewing: at compute cycle t, row i receives A[i][t-i] and column j receives
// B[t-j][j] (zero outside 0..N-1). PE(i,j) then sees A[i][k] and B[k][j] for
// the same k = t-i-j. The last product reaches PE(N-1,N-1) at t = 3N-3, so
// COMPUTE lasts 3N-2 cycles.
//
// FSM: IDLE -> LOAD (clear array) -> COMPUTE -> DRAIN (copy to C buffer) -> DONE
// ---------------------------------------------------------------------------
module accel_core #(
  parameter int N  = 4,
  parameter int DW = 8,
  parameter int AW = 32
) (
  input  logic              clk,
  input  logic              rst_n,
  input  logic              start,       // 1-cycle pulse, ignored when busy
  input  logic              clear_c,     // 1-cycle pulse, zeroes C buffer (ignored when busy)
  input  logic [N*N*DW-1:0] a_mat,
  input  logic [N*N*DW-1:0] b_mat,
  output logic [N*N*AW-1:0] c_mat,
  output logic              busy,
  output logic              done_pulse   // 1-cycle pulse when C is valid
);
  typedef enum logic [2:0] {S_IDLE, S_LOAD, S_COMPUTE, S_DRAIN, S_DONE} state_t;
  state_t state;

  localparam int LAST_T = 3*N - 3;
  localparam int TW     = $clog2(3*N);

  logic [TW-1:0]     t;
  logic [N*DW-1:0]   a_left, b_top;
  logic [N*N*AW-1:0] acc_flat;
  logic              arr_clr, arr_en;

  assign busy       = (state != S_IDLE);
  assign arr_clr    = (state == S_LOAD);
  assign arr_en     = (state == S_COMPUTE);
  assign done_pulse = (state == S_DONE);

  // Zero-extended counter so comparisons with integer loop variables are 32-bit
  logic [31:0] t32;
  assign t32 = {{(32-TW){1'b0}}, t};

  // Input skew logic: row r gets A[r][k] and column r gets B[k][r] when t == r + k
  always_comb begin
    a_left = '0;
    b_top  = '0;
    if (state == S_COMPUTE) begin
      for (int r = 0; r < N; r++) begin
        for (int k = 0; k < N; k++) begin
          if (t32 == r + k) begin
            a_left[r*DW +: DW] = a_mat[(r*N + k)*DW +: DW];
            b_top [r*DW +: DW] = b_mat[(k*N + r)*DW +: DW];
          end
        end
      end
    end
  end

  systolic_array #(.N(N), .DW(DW), .AW(AW)) u_array (
    .clk      (clk),
    .rst_n    (rst_n),
    .clr      (arr_clr),
    .en       (arr_en),
    .a_left   (a_left),
    .b_top    (b_top),
    .acc_flat (acc_flat)
  );

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= S_IDLE;
      t     <= '0;
      c_mat <= '0;
    end else begin
      case (state)
        S_IDLE: begin
          t <= '0;
          if (start)        state <= S_LOAD;
          else if (clear_c) c_mat <= '0;
        end
        S_LOAD:    state <= S_COMPUTE;
        S_COMPUTE: begin
          if (t32 == LAST_T) state <= S_DRAIN;
          else                   t <= t + 1'b1;
        end
        S_DRAIN: begin
          c_mat <= acc_flat;
          state <= S_DONE;
        end
        S_DONE:  state <= S_IDLE;
        default: state <= S_IDLE;
      endcase
    end
  end
endmodule

// ==== rtl/axil_slave.sv ====
// ---------------------------------------------------------------------------
// axil_slave.sv - AXI4-Lite register block for the systolic accelerator.
//
// Register map (byte offsets, 32-bit registers):
//   0x000 CTRL    RW  bit0 START (self-clearing, reads 0), bit1 CLR_C (self-clearing),
//                     bit2 IRQ_EN.  Any write while BUSY -> SLVERR.
//   0x004 STATUS  RO/W1C  bit0 BUSY, bit1 DONE (write 1 to clear; START also clears it).
//   0x008 DIM     RO  N
//   0x100 + 4*i   A_BUF  RW  row i of A, byte k = A[i][k]. Write while BUSY -> SLVERR.
//   0x200 + 4*k   B_BUF  RW  row k of B, byte j = B[k][j]. Write while BUSY -> SLVERR.
//   0x300 + 4*(i*N+j) C_BUF RO  C[i][j] (signed 32-bit). Read while BUSY -> SLVERR.
//   Anything else -> SLVERR. Writes to RO registers -> SLVERR.
//   addr[1:0] is ignored; byte lanes are selected by WSTRB.
//
// Handles AW and W arriving in either order or together. One outstanding
// write and one outstanding read at a time (allowed by AXI4-Lite).
// Requires N <= 4 so one matrix row fits in one 32-bit word.
// ---------------------------------------------------------------------------
module axil_slave #(
  parameter int N      = 4,
  parameter int DW     = 8,
  parameter int AW     = 32,
  parameter int ADDR_W = 12
) (
  input  logic              clk,
  input  logic              rst_n,
  // AXI4-Lite slave
  input  logic [ADDR_W-1:0] s_axil_awaddr,
  input  logic [2:0]        s_axil_awprot,
  input  logic              s_axil_awvalid,
  output logic              s_axil_awready,
  input  logic [31:0]       s_axil_wdata,
  input  logic [3:0]        s_axil_wstrb,
  input  logic              s_axil_wvalid,
  output logic              s_axil_wready,
  output logic [1:0]        s_axil_bresp,
  output logic              s_axil_bvalid,
  input  logic              s_axil_bready,
  input  logic [ADDR_W-1:0] s_axil_araddr,
  input  logic [2:0]        s_axil_arprot,
  input  logic              s_axil_arvalid,
  output logic              s_axil_arready,
  output logic [31:0]       s_axil_rdata,
  output logic [1:0]        s_axil_rresp,
  output logic              s_axil_rvalid,
  input  logic              s_axil_rready,
  // To / from the core
  output logic [N*N*DW-1:0] a_mat,
  output logic [N*N*DW-1:0] b_mat,
  input  logic [N*N*AW-1:0] c_mat,
  output logic              start,
  output logic              clear_c,
  input  logic              core_busy,
  input  logic              done_pulse,
  output logic              irq
);
  localparam logic [1:0] RESP_OKAY   = 2'b00;
  localparam logic [1:0] RESP_SLVERR = 2'b10;

  localparam logic [ADDR_W-1:0] OFF_CTRL   = 'h000;
  localparam logic [ADDR_W-1:0] OFF_STATUS = 'h004;
  localparam logic [ADDR_W-1:0] OFF_DIM    = 'h008;
  localparam logic [ADDR_W-1:0] OFF_A      = 'h100;
  localparam logic [ADDR_W-1:0] OFF_B      = 'h200;
  localparam logic [ADDR_W-1:0] OFF_C      = 'h300;

  // ----------------------------------------------------------------------
  // State
  // ----------------------------------------------------------------------
  logic irq_en, done;
  logic busy;   // core busy, or a START accepted but not yet seen by the core
  assign busy = core_busy | start;
  assign irq  = done & irq_en;

  // Write channel holding registers
  logic              aw_hold, w_hold;
  logic [ADDR_W-1:0] aw_addr_q;
  logic [31:0]       w_data_q;
  logic [3:0]        w_strb_q;

  assign s_axil_awready = !aw_hold && !s_axil_bvalid;
  assign s_axil_wready  = !w_hold  && !s_axil_bvalid;
  assign s_axil_arready = !s_axil_rvalid;

  // ----------------------------------------------------------------------
  // Address decode (word addresses; addr[1:0] ignored, WSTRB selects bytes)
  // ----------------------------------------------------------------------
  localparam int WW = ADDR_W - 2;   // word-address width
  localparam logic [WW-1:0] W_CTRL   = OFF_CTRL[ADDR_W-1:2];
  localparam logic [WW-1:0] W_STATUS = OFF_STATUS[ADDR_W-1:2];
  localparam logic [WW-1:0] W_DIM    = OFF_DIM[ADDR_W-1:2];
  localparam logic [WW-1:0] W_A      = OFF_A[ADDR_W-1:2];
  localparam logic [WW-1:0] W_B      = OFF_B[ADDR_W-1:2];
  localparam logic [WW-1:0] W_C      = OFF_C[ADDR_W-1:2];
  localparam int            NN       = N * N;
  localparam logic [WW-1:0] N_W      = N[WW-1:0];
  localparam logic [WW-1:0] NN_W     = NN[WW-1:0];

  logic [WW-1:0] aw_word, ar_word;
  assign aw_word = aw_addr_q[ADDR_W-1:2];
  assign ar_word = s_axil_araddr[ADDR_W-1:2];

  logic aw_ctrl, aw_status, aw_a, aw_b;
  logic ar_ctrl, ar_status, ar_dim, ar_a, ar_b, ar_c;
  assign aw_ctrl   = (aw_word == W_CTRL);
  assign aw_status = (aw_word == W_STATUS);
  assign aw_a      = (aw_word >= W_A) && (aw_word < W_A + N_W);
  assign aw_b      = (aw_word >= W_B) && (aw_word < W_B + N_W);
  assign ar_ctrl   = (ar_word == W_CTRL);
  assign ar_status = (ar_word == W_STATUS);
  assign ar_dim    = (ar_word == W_DIM);
  assign ar_a      = (ar_word >= W_A) && (ar_word < W_A + N_W);
  assign ar_b      = (ar_word >= W_B) && (ar_word < W_B + N_W);
  assign ar_c      = (ar_word >= W_C) && (ar_word < W_C + NN_W);

  // Element offsets inside each buffer, zero-extended to 32 bits for indexing
  logic [WW-1:0] aw_off_a, aw_off_b, ar_off_a, ar_off_b, ar_off_c;
  assign aw_off_a = aw_word - W_A;
  assign aw_off_b = aw_word - W_B;
  assign ar_off_a = ar_word - W_A;
  assign ar_off_b = ar_word - W_B;
  assign ar_off_c = ar_word - W_C;

  logic [31:0] aw_ia, aw_ib, ar_ia, ar_ib, ar_ic;
  assign aw_ia = {{(32-WW){1'b0}}, aw_off_a};
  assign aw_ib = {{(32-WW){1'b0}}, aw_off_b};
  assign ar_ia = {{(32-WW){1'b0}}, ar_off_a};
  assign ar_ib = {{(32-WW){1'b0}}, ar_off_b};
  assign ar_ic = {{(32-WW){1'b0}}, ar_off_c};

  // ----------------------------------------------------------------------
  // Write path
  // ----------------------------------------------------------------------
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      aw_hold       <= 1'b0;
      w_hold        <= 1'b0;
      aw_addr_q     <= '0;
      w_data_q      <= '0;
      w_strb_q      <= '0;
      s_axil_bvalid <= 1'b0;
      s_axil_bresp  <= RESP_OKAY;
      a_mat         <= '0;
      b_mat         <= '0;
      start         <= 1'b0;
      clear_c       <= 1'b0;
      irq_en        <= 1'b0;
      done          <= 1'b0;
    end else begin
      start   <= 1'b0;
      clear_c <= 1'b0;

      // Capture AW and W independently
      if (s_axil_awvalid && s_axil_awready) begin
        aw_hold   <= 1'b1;
        aw_addr_q <= s_axil_awaddr;
      end
      if (s_axil_wvalid && s_axil_wready) begin
        w_hold   <= 1'b1;
        w_data_q <= s_axil_wdata;
        w_strb_q <= s_axil_wstrb;
      end

      // Release the write response
      if (s_axil_bvalid && s_axil_bready)
        s_axil_bvalid <= 1'b0;

      // Perform the write once both halves are captured
      if (aw_hold && w_hold && !s_axil_bvalid) begin
        aw_hold       <= 1'b0;
        w_hold        <= 1'b0;
        s_axil_bvalid <= 1'b1;
        s_axil_bresp  <= RESP_OKAY;

        if (aw_ctrl) begin
          if (busy) begin
            s_axil_bresp <= RESP_SLVERR;
          end else if (w_strb_q[0]) begin
            start   <= w_data_q[0];
            clear_c <= w_data_q[1];
            irq_en  <= w_data_q[2];
            if (w_data_q[0]) done <= 1'b0;   // a new run clears DONE
          end
        end else if (aw_status) begin
          if (w_strb_q[0] && w_data_q[1]) done <= 1'b0;   // W1C
        end else if (aw_a) begin
          if (busy) s_axil_bresp <= RESP_SLVERR;
          else begin
            for (int b = 0; b < N; b++)
              if (w_strb_q[b])
                a_mat[(aw_ia*N + b)*DW +: DW] <= w_data_q[b*8 +: 8];
          end
        end else if (aw_b) begin
          if (busy) s_axil_bresp <= RESP_SLVERR;
          else begin
            for (int b = 0; b < N; b++)
              if (w_strb_q[b])
                b_mat[(aw_ib*N + b)*DW +: DW] <= w_data_q[b*8 +: 8];
          end
        end else begin
          // DIM, C_BUF (read-only) and unmapped addresses
          s_axil_bresp <= RESP_SLVERR;
        end
      end

      // DONE is set by the core; setting wins over a same-cycle clear
      if (done_pulse) done <= 1'b1;
    end
  end

  // ----------------------------------------------------------------------
  // Read path
  // ----------------------------------------------------------------------
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      s_axil_rvalid <= 1'b0;
      s_axil_rdata  <= '0;
      s_axil_rresp  <= RESP_OKAY;
    end else begin
      if (s_axil_rvalid && s_axil_rready)
        s_axil_rvalid <= 1'b0;

      if (s_axil_arvalid && s_axil_arready) begin
        s_axil_rvalid <= 1'b1;
        s_axil_rresp  <= RESP_OKAY;
        s_axil_rdata  <= '0;

        if (ar_ctrl) begin
          s_axil_rdata <= {29'b0, irq_en, 2'b00};
        end else if (ar_status) begin
          s_axil_rdata <= {30'b0, done, busy};
        end else if (ar_dim) begin
          s_axil_rdata <= N;
        end else if (ar_a) begin
          for (int b = 0; b < N; b++)
            s_axil_rdata[b*8 +: 8] <= a_mat[(ar_ia*N + b)*DW +: DW];
        end else if (ar_b) begin
          for (int b = 0; b < N; b++)
            s_axil_rdata[b*8 +: 8] <= b_mat[(ar_ib*N + b)*DW +: DW];
        end else if (ar_c) begin
          if (busy) s_axil_rresp <= RESP_SLVERR;
          else      s_axil_rdata <= c_mat[ar_ic*AW +: 32];
        end else begin
          s_axil_rresp <= RESP_SLVERR;
        end
      end
    end
  end

  // Unused inputs: AXI protection bits and the byte offset of the address
  logic unused;
  assign unused = ^{s_axil_awprot, s_axil_arprot, aw_addr_q[1:0], s_axil_araddr[1:0]};
endmodule

// ==== rtl/accel_top.sv ====
// ---------------------------------------------------------------------------
// accel_top.sv - AXI4-Lite systolic-array matrix-multiply accelerator.
// ---------------------------------------------------------------------------
module accel_top #(
  parameter int N      = 4,     // array size, 1..4
  parameter int ADDR_W = 12
) (
  input  logic              clk,
  input  logic              rst_n,
  input  logic [ADDR_W-1:0] s_axil_awaddr,
  input  logic [2:0]        s_axil_awprot,
  input  logic              s_axil_awvalid,
  output logic              s_axil_awready,
  input  logic [31:0]       s_axil_wdata,
  input  logic [3:0]        s_axil_wstrb,
  input  logic              s_axil_wvalid,
  output logic              s_axil_wready,
  output logic [1:0]        s_axil_bresp,
  output logic              s_axil_bvalid,
  input  logic              s_axil_bready,
  input  logic [ADDR_W-1:0] s_axil_araddr,
  input  logic [2:0]        s_axil_arprot,
  input  logic              s_axil_arvalid,
  output logic              s_axil_arready,
  output logic [31:0]       s_axil_rdata,
  output logic [1:0]        s_axil_rresp,
  output logic              s_axil_rvalid,
  input  logic              s_axil_rready,
  output logic              irq
);
  localparam int DW = 8;
  localparam int AW = 32;

  logic [N*N*DW-1:0] a_mat, b_mat;
  logic [N*N*AW-1:0] c_mat;
  logic              start, clear_c, core_busy, done_pulse;

  axil_slave #(.N(N), .DW(DW), .AW(AW), .ADDR_W(ADDR_W)) u_regs (
    .clk, .rst_n,
    .s_axil_awaddr, .s_axil_awprot, .s_axil_awvalid, .s_axil_awready,
    .s_axil_wdata, .s_axil_wstrb, .s_axil_wvalid, .s_axil_wready,
    .s_axil_bresp, .s_axil_bvalid, .s_axil_bready,
    .s_axil_araddr, .s_axil_arprot, .s_axil_arvalid, .s_axil_arready,
    .s_axil_rdata, .s_axil_rresp, .s_axil_rvalid, .s_axil_rready,
    .a_mat, .b_mat, .c_mat, .start, .clear_c,
    .core_busy, .done_pulse, .irq
  );

  accel_core #(.N(N), .DW(DW), .AW(AW)) u_core (
    .clk, .rst_n,
    .start, .clear_c,
    .a_mat, .b_mat, .c_mat,
    .busy       (core_busy),
    .done_pulse (done_pulse)
  );
endmodule
